}
const photo = (id: string, width = 1000) => "'`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${width}&q=85`;
const articles = [
  { id: 1, category: '"'Пространство', title: 'Дом, в котором хочется остаться', description: 'Как свет, простые формы и натуральные материалы меняют ощущение дома.', image: photo('photo-1600210492486-724fe5c67fb0'), time: 7, collection: 'Искусство простоты', body: ['Дом начинается с ощущения. С утреннего света на стене, знакомой фактуры дерева под ладонью и любимого кресла, в котором удобно ничего не делать.', 'Чтобы пространство стало своим, ему не обязательно быть идеальным. Оставьте на виду вещи с историей: керамическую чашку из путешествия, фотографии, книги с закладками. Именно они превращают интерьер в место, куда хочется возвращаться.', 'Попробуйте начать с одного уголка. Уберите лишнее, передвиньте кресло ближе к окну, добавьте мягкий свет. Понаблюдайте, как маленькая перемена влияет на весь день. Иногда для нового ощущения дома достаточно просто дать ему немного воздуха.'] },
