      <div className=\"sidebar-bottom\"><div className=\"quiet-note\"><Icon name=\"leaf\" size={25}/><p>Меньше шума.<br/>Больше вдохновения.</p><span>Место для того, что важно.</span></div>
      <div className=\"theme-label\">Внешний вид</div><div className=\"theme-switch\" aria-label=\"Выбор темы\"><button className={"'!dark ? '"'selected' : ''} onClick={() => setDark(false)} aria-pressed={"'!dark}><Icon name="sun" size={17}/>Светлая</button><button className={dark ? '"'selected' : ''} onClick={() => setDark(true)} aria-pressed={dark}><Icon name=\"moon\" size={17}/>Тёмная</button></div>
